using FluentValidation;namespace SchoolERP.Application.Features.Departments;
public sealed class CreateDepartmentRequestValidator:AbstractValidator<CreateDepartmentRequest>{public CreateDepartmentRequestValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.Type).IsInEnum();RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.HeadName).MaximumLength(200);RuleFor(x=>x.Email).MaximumLength(320).EmailAddress().When(x=>!string.IsNullOrWhiteSpace(x.Email));RuleFor(x=>x.Phone).MaximumLength(30);RuleFor(x=>x.Location).MaximumLength(200);RuleFor(x=>x.Description).MaximumLength(1000);}}
public sealed class UpdateDepartmentRequestValidator:AbstractValidator<UpdateDepartmentRequest>{public UpdateDepartmentRequestValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.Type).IsInEnum();RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.HeadName).MaximumLength(200);RuleFor(x=>x.Email).MaximumLength(320).EmailAddress().When(x=>!string.IsNullOrWhiteSpace(x.Email));RuleFor(x=>x.Phone).MaximumLength(30);RuleFor(x=>x.Location).MaximumLength(200);RuleFor(x=>x.Description).MaximumLength(1000);}}
public sealed class ChangeDepartmentCodeRequestValidator:AbstractValidator<ChangeDepartmentCodeRequest>{public ChangeDepartmentCodeRequestValidator()=>RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");}
